<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Autonomous Cave Flyer</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { background: #05050d; overflow: hidden; font-family: monospace; }
    canvas { display: block; width: 100vw; height: 100vh; }
  </style>
</head>
<body>
  <canvas id="c"></canvas>
  <script>
    const canvas = document.getElementById('c');
    const ctx = canvas.getContext('2d');

    let w, h;
    function resize() {
      w = canvas.width = window.innerWidth;
      h = canvas.height = window.innerHeight;
    }
    resize();
    window.addEventListener('resize', resize);

    // Cave slice configuration
    const step = 8;
    const slices = [];
    let worldT = 0;
    const speed = 4;
    let distance = 0;

    // Procedural terrain generation using compound sine waves
    function getCaveBounds(t) {
      const centerY = (h * 0.5) +
        Math.sin(t * 0.004) * (h * 0.22) +
        Math.sin(t * 0.011) * (h * 0.12) +
        Math.cos(t * 0.023) * (h * 0.06);

      const corridorHeight = Math.max(130, (h * 0.32) + Math.sin(t * 0.007) * (h * 0.08));

      return {
        top: Math.max(10, centerY - corridorHeight / 2),
        bottom: Math.min(h - 10, centerY + corridorHeight / 2)
      };
    }

    // Populate initial cave slices across the screen
    for (let x = 0; x <= w + step * 2; x += step) {
      slices.push({ x, ...getCaveBounds(worldT) });
      worldT += step;
    }

    // Ship state
    const ship = {
      x: 180,
      y: h / 2,
      vy: 0,
      angle: 0,
      size: 14,
      particles: []
    };

    function update() {
      distance += speed * 0.25;

      // Scroll cave
      for (let i = 0; i < slices.length; i++) {
        slices[i].x -= speed;
      }

      // Remove offscreen slice and append new one
      while (slices.length > 0 && slices[0].x < -step) {
        slices.shift();
      }
      const lastX = slices[slices.length - 1].x;
      slices.push({ x: lastX + step, ...getCaveBounds(worldT) });
      worldT += step;

      // Autopilot: Look ahead along the corridor and steer toward the upcoming center
      const lookaheadX = ship.x + 140;
      let targetCenter = h / 2;

      for (let i = 0; i < slices.length - 1; i++) {
        if (slices[i].x <= lookaheadX && slices[i + 1].x >= lookaheadX) {
          const ratio = (lookaheadX - slices[i].x) / step;
          const top = slices[i].top + (slices[i + 1].top - slices[i].top) * ratio;
          const bottom = slices[i].bottom + (slices[i + 1].bottom - slices[i].bottom) * ratio;
          targetCenter = (top + bottom) / 2;
          break;
        }
      }

      // PD controller (Proportional-Derivative) to smoothly correct vertical path
      const error = targetCenter - ship.y;
      const targetVy = error * 0.08;
      const thrust = (targetVy - ship.vy) * 0.14;

      ship.vy += Math.max(-0.6, Math.min(0.6, thrust));
      ship.vy *= 0.96; // Air resistance damping
      ship.y += ship.vy;

      // Smooth pitch rotation based on velocity
      ship.angle = Math.atan2(ship.vy, speed * 1.5);

      // Spawn thruster particles
      ship.particles.push({
        x: ship.x - Math.cos(ship.angle) * ship.size,
        y: ship.y - Math.sin(ship.angle) * ship.size,
        vx: -speed * 0.7 + (Math.random() - 0.5) * 1.5,
        vy: (Math.random() - 0.5) * 1.5,
        life: 1.0
      });

      for (let i = ship.particles.length - 1; i >= 0; i--) {
        const p = ship.particles[i];
        p.x += p.vx;
        p.y += p.vy;
        p.life -= 0.035;
        if (p.life <= 0) ship.particles.splice(i, 1);
      }
    }

    function draw() {
      ctx.fillStyle = '#070714';
      ctx.fillRect(0, 0, w, h);

      // Draw cave ceiling
      ctx.beginPath();
      ctx.moveTo(slices[0].x, 0);
      for (const s of slices) ctx.lineTo(s.x, s.top);
      ctx.lineTo(w, 0);
      ctx.closePath();
      ctx.fillStyle = '#101426';
      ctx.fill();

      // Ceiling glowing boundary
      ctx.beginPath();
      for (let i = 0; i < slices.length; i++) {
        if (i === 0) ctx.moveTo(slices[i].x, slices[i].top);
        else ctx.lineTo(slices[i].x, slices[i].top);
      }
      ctx.strokeStyle = '#00f0ff';
      ctx.lineWidth = 3;
      ctx.shadowColor = '#00f0ff';
      ctx.shadowBlur = 10;
      ctx.stroke();

      // Draw cave floor
      ctx.beginPath();
      ctx.moveTo(slices[0].x, h);
      for (const s of slices) ctx.lineTo(s.x, s.bottom);
      ctx.lineTo(w, h);
      ctx.closePath();
      ctx.fillStyle = '#101426';
      ctx.shadowBlur = 0;
      ctx.fill();

      // Floor glowing boundary
      ctx.beginPath();
      for (let i = 0; i < slices.length; i++) {
        if (i === 0) ctx.moveTo(slices[i].x, slices[i].bottom);
        else ctx.lineTo(slices[i].x, slices[i].bottom);
      }
      ctx.strokeStyle = '#ff0077';
      ctx.lineWidth = 3;
      ctx.shadowColor = '#ff0077';
      ctx.shadowBlur = 10;
      ctx.stroke();
      ctx.shadowBlur = 0;

      // Draw thruster exhaust trail
      for (const p of ship.particles) {
        ctx.fillStyle = `rgba(0, 240, 255, ${p.life})`;
        ctx.fillRect(p.x, p.y, 3, 3);
      }

      // Draw ship
      ctx.save();
      ctx.translate(ship.x, ship.y);
      ctx.rotate(ship.angle);

      ctx.beginPath();
      ctx.moveTo(ship.size * 1.2, 0);
      ctx.lineTo(-ship.size * 0.8, -ship.size * 0.6);
      ctx.lineTo(-ship.size * 0.4, 0);
      ctx.lineTo(-ship.size * 0.8, ship.size * 0.6);
      ctx.closePath();

      ctx.fillStyle = '#ffffff';
      ctx.shadowColor = '#00ffff';
      ctx.shadowBlur = 12;
      ctx.fill();

      // Cockpit glow
      ctx.beginPath();
      ctx.arc(2, 0, 3, 0, Math.PI * 2);
      ctx.fillStyle = '#ff0077';
      ctx.fill();
      ctx.restore();

      // Distance HUD
      ctx.shadowBlur = 0;
      ctx.fillStyle = '#ffffff';
      ctx.font = 'bold 20px monospace';
      ctx.fillText(`AUTOPILOT: ENGAGED`, 30, 45);
      ctx.fillStyle = '#00f0ff';
      ctx.font = '16px monospace';
      ctx.fillText(`DISTANCE: ${Math.floor(distance)} m`, 30, 72);
    }

    function loop() {
      update();
      draw();
      requestAnimationFrame(loop);
    }
    loop();
  </script>
</body>
</html>
```

The game continuously generates a procedural, scrolling cave corridor using layered sine waves while an onboard predictive PD controller samples the upcoming safe midpoint ahead of the ship to steer vertical thrusters and seamlessly avoid collisions.
